package com.example.starter.race.api;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * 分组划分请求：OPEN 赛事生成名单前一次性把选手划入 2~8 个分组，
 * 每组 2~16 人，同一选手只属一个分组；成功后版本加一且不可改写。
 *
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 * @param groups          分组定义，顺序即分组顺序（position 从1连续分配）
 */
public record AssignGroupsRequest(
        @NotNull Integer expectedVersion,
        @NotBlank String requestId,
        @NotEmpty @Valid List<GroupDefinition> groups
) {

    /**
     * 单个分组定义。
     *
     * @param groupCode 分组代码，赛事内唯一
     * @param members   成员参赛号列表，每组 2~16 人且跨组不重复
     */
    public record GroupDefinition(
            @NotBlank String groupCode,
            @NotEmpty List<@NotBlank String> members
    ) {
    }
}

package com.example.starter.race.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 晋级名单生成请求：在一个事务内按当前一致状态选出每组前 Q 名直接晋级，
 * 再从各组未直接晋级者中全局取前 W 名补位；并列跨过边界时全部纳入。
 *
 * @param advancementKey  晋级名单键，全局唯一，撤销后也不可复用
 * @param directQuota     每组直接晋级数 Q（1~8）
 * @param wildcardQuota   跨组补位名额 W（0~8）
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键：同参重放首次结果，异参409，失败不占键）
 */
public record GenerateAdvancementRequest(
        @NotBlank String advancementKey,
        @Min(1) @Max(8) Integer directQuota,
        @Min(0) @Max(8) Integer wildcardQuota,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 整份撤销生效晋级名单请求：原快照保留为 REVOKED，之后可重新生成；封榜后禁止撤销。
 *
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record RevokeAdvancementRequest(
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

